import{Z as t,e as s,f as a,a0 as i}from"./chunks/framework.DmpHOl9T.js";const c=JSON.parse('{"title":"Hidden","description":"","frontmatter":{},"headers":[],"relativePath":"fields/hidden.md","filePath":"fields/hidden.md","lastUpdated":1781222763000}'),n={name:"fields/hidden.md"};function r(o,e,l,d,h,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="hidden" tabindex="-1">Hidden <a class="header-anchor" href="#hidden" aria-label="Permalink to &quot;Hidden&quot;">​</a></h1><p>Use Hidden when the form needs to carry a value without showing it to the person filling out the form.</p><p>Hidden fields are useful for context, attribution, and routing data. Do not rely on them for security-sensitive decisions because hidden values can still be changed before submission.</p><h2 id="key-settings" tabindex="-1">Key Settings <a class="header-anchor" href="#key-settings" aria-label="Permalink to &quot;Key Settings&quot;">​</a></h2><ul><li><strong>Default value</strong> - Set the value submitted with the form.</li><li><strong>Value source</strong> - Populate from a preset, <strong>Custom Value</strong>, <strong>Template</strong>, query string parameter, or cookie where supported.</li><li><strong>Custom Value</strong> - Literal text with optional variable-picker tokens (<code>{field:handle}</code>, <code>{form:handle}</code>, and so on). If the visitor submits a non-empty value, that posted value is stored.</li><li><strong>Template</strong> - A Craft <a href="https://craftcms.com/docs/5.x/system/object-templates.html" target="_blank" rel="noreferrer">object template</a> resolved <strong>only on the server</strong>. Posted values are ignored. Use this for trusted computed values such as event context, custom <code>currentUser</code> fields, or query parameters via <code>{request.param.myParam}</code>.</li><li><strong>Prefill query parameter</strong> - Read a value from a specific query string parameter.</li><li><strong>Handle</strong> - Choose a stable field handle for integrations, templates and exports.</li></ul><h2 id="custom-value-vs-template" tabindex="-1">Custom Value vs Template <a class="header-anchor" href="#custom-value-vs-template" aria-label="Permalink to &quot;Custom Value vs Template&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Custom Value</th><th>Template</th></tr></thead><tbody><tr><td>Editor</td><td>Variable picker</td><td>Object-template code editor</td></tr><tr><td>Posted value</td><td>Stored when non-empty</td><td><strong>Ignored</strong> — server re-resolves on every save</td></tr><tr><td>Trust model</td><td>User-modifiable</td><td>Server-authoritative</td></tr></tbody></table><p>Use <strong>Template</strong> when the hidden value must not be tampered with (for example event cost, entitlement flags, or routing metadata). Use <strong>Custom Value</strong> for tracking tokens or values that may legitimately vary per submission.</p><p>Extend template context in PHP with <code>HiddenDefaultTemplateResolver::EVENT_DEFINE_CONTEXT</code> when you need entry lookups or other project-specific variables.</p><h2 id="submitted-value" tabindex="-1">Submitted Value <a class="header-anchor" href="#submitted-value" aria-label="Permalink to &quot;Submitted Value&quot;">​</a></h2><p>Hidden stores a submitted value like other fields, even though the user does not see a visible control. For <strong>Custom Value</strong> and preset sources, treat the stored value as user-modifiable browser data unless you validate it server-side. <strong>Template</strong> defaults are re-resolved on the server and ignore posted input.</p><p>When querying or saving submissions through GraphQL, the field handle is used as the field name. Query the form’s <code>formFields</code> and include <code>inputTypeName</code> if you need to confirm the generated input type for a specific form.</p><h2 id="theme-config" tabindex="-1">Theme Config <a class="header-anchor" href="#theme-config" aria-label="Permalink to &quot;Theme Config&quot;">​</a></h2><p>The Hidden field can be targeted with the <code>hiddenField</code> theme config key.</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contactForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    themeConfig: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        hiddenField: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            field: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                attributes: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                    data: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                        tracking: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;campaign&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) }}</span></span></code></pre></div><p>Hidden fields usually need little presentation customisation. Use a template override only when the hidden input output itself needs to change.</p><p>For full Tailwind, Bootstrap and other framework examples, see <a href="https://github.com/verbb/formie-theme-configs" target="_blank" rel="noreferrer">Formie theme configs</a>.</p><h2 id="front-end-reference" tabindex="-1">Front-End Reference <a class="header-anchor" href="#front-end-reference" aria-label="Permalink to &quot;Front-End Reference&quot;">​</a></h2><p>Hidden fields are still rendered into the page HTML. Do not place secrets, trusted prices, permission flags or other security-sensitive values in a hidden field without server-side validation.</p><p>The front-end docs live on the separate browser UI reference site and cover rendered markup, data attributes, styling classes and JavaScript behaviour for custom front-end implementations.</p><ul><li><a href="https://docs.verbb.io/formie/browser/ui-reference/fields/hidden" target="_blank" rel="noreferrer">Hidden</a></li></ul><h2 id="related-fields" tabindex="-1">Related Fields <a class="header-anchor" href="#related-fields" aria-label="Permalink to &quot;Related Fields&quot;">​</a></h2><ul><li>Use <a href="/fields/single-line-text">Single-Line Text</a> when the user should see and edit the value.</li></ul>`,23)])])}const m=t(n,[["render",r]]);export{c as __pageData,m as default};
